--

CREATE TABLE public.payroll_vacation_policies (
    id bigint NOT NULL,
    name character varying(255) NOT NULL,
    start_date date NOT NULL,
    end_date date,
    vacation_periods character varying(255) NOT NULL,
    vacation_type character varying(255) NOT NULL,
    vacation_advance boolean DEFAULT false NOT NULL,
    vacation_postpone boolean DEFAULT false NOT NULL,
    staff_antiquity boolean DEFAULT false NOT NULL,
    vacation_periods_accumulated_per_year integer,
    vacation_days integer,
    vacation_period_per_year integer,
    additional_days_per_year integer,
    minimum_additional_days_per_year integer,
    maximum_additional_days_per_year integer,
    institution_id bigint NOT NULL,
    created_at timestamp(0) without time zone,
    updated_at timestamp(0) without time zone,
    deleted_at timestamp(0) without time zone,
    payroll_payment_type_id bigint,
    active boolean DEFAULT false NOT NULL,
    assign_to text,
    on_scale boolean DEFAULT false,
    worker_arises boolean DEFAULT false,
    generate_worker_arises character varying(15),
    min_days_advance integer,
    group_by character varying(255),
    type character varying(255),
    days_on_scale character varying(255),
    days_group_by character varying(255),
    days_type character varying(255),
    business_days boolean DEFAULT false,
    old_jobs boolean DEFAULT false,
    from_year integer,
    years_for_additional_days integer DEFAULT 1,
    CONSTRAINT payroll_vacation_policies_vacation_type_check CHECK (((vacation_type)::text = ANY (ARRAY[('collective_vacations'::character varying)::text, ('vacation_period'::character varying)::text])))
);


