CREATE TABLE public.work_attendance_permissions (
    id bigint NOT NULL,
    start_date_at date NOT NULL,
    start_time_at time(0) without time zone,
    end_date_at date NOT NULL,
    end_time_at time(0) without time zone,
    reason text NOT NULL,
    status character varying(255) DEFAULT 'pending'::character varying NOT NULL,
    comments text,
    payroll_staff_id bigint NOT NULL,
    created_at timestamp(0) without time zone,
    updated_at timestamp(0) without time zone,
    deleted_at timestamp(0) without time zone,
    CONSTRAINT work_attendance_permissions_status_check CHECK (((status)::text = ANY (ARRAY[('pending'::character varying)::text, ('approved'::character varying)::text, ('rejected'::character varying)::text])))
);


